import{bV as i,aL as e,u as t,G as p}from"./chunks/framework.O9JQzcbi.js";const d=JSON.parse('{"title":"前端 Vscode 常用插件","description":"","frontmatter":{"title":"前端 Vscode 常用插件","date":"2023-05-07T00:00:00.000Z","categories":["Vscode"],"tags":["plugin"]},"headers":[],"relativePath":"log/vscode/vscode-plugin.md","filePath":"log/vscode/vscode-plugin.md","lastUpdated":1789838113000}'),o={name:"log/vscode/vscode-plugin.md"};function g(m,a,c,n,s,r){return e(),t("div",null,[...a[0]||(a[0]=[p('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /log/vscode/vscode-plugin.md for this page in Markdown format</div><h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><p>收集常用 前端 vscode 插件 让开发事半功倍</p><h2 id="外观优化" tabindex="-1">外观优化 <a class="header-anchor" href="#外观优化" aria-label="Permalink to &quot;外观优化&quot;">​</a></h2><h3 id="主题色" tabindex="-1">主题色 <a class="header-anchor" href="#主题色" aria-label="Permalink to &quot;主题色&quot;">​</a></h3><p>Community Material Theme / Material Theme</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112453685.png?imageMogr2/quality/70" alt="image-20230331112453685"></p><p>Atom One Dark Theme / Atom One Light Theme</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112428414.png?imageMogr2/quality/70" alt="image-20230331112428414"></p><p>Gruvbox theme</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112408426.png?imageMogr2/quality/70" alt="image-20230331112408426"></p><p>Palenight Theme</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112345232.png?imageMogr2/quality/70" alt="image-20230331112345232"></p><p>Bearded Theme</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112326630.png?imageMogr2/quality/70" alt="image-20230331112326630"></p><h3 id="文件-icon" tabindex="-1">文件 icon <a class="header-anchor" href="#文件-icon" aria-label="Permalink to &quot;文件 icon&quot;">​</a></h3><p>Material Icon Theme</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112132706.png?imageMogr2/quality/70" alt="image-20230331112132706"></p><p>Vscode-icons</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112200920.png?imageMogr2/quality/70" alt="image-20230331112200920"></p><p>DotEnv</p><p>.env 文件提供代码高亮</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331114757361.png?imageMogr2/quality/70" alt="image-20230331114757361"></p><h3 id="代码辅助" tabindex="-1">代码辅助 <a class="header-anchor" href="#代码辅助" aria-label="Permalink to &quot;代码辅助&quot;">​</a></h3><p>Better Comments</p><p>它将帮助你在代码中创建更人性化的注释，你将能够使用此扩展对注释进行分类：</p><ul><li>警报</li><li>查询</li><li>待办事项</li><li>强调</li></ul><p>注释掉的代码也可以设置样式以表明它不应该出现。</p><p>可以在设置中指定所需的任何其他注释样式。</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112224556.png?imageMogr2/quality/70" alt="image-20230331112224556"></p><p>indent-rainbow 彩虹缩进，代码不同的缩进展示不同的颜色</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112249721.png?imageMogr2/quality/70" alt="image-20230331112249721"></p><h2 id="前端开发必备插件" tabindex="-1">前端开发必备插件 <a class="header-anchor" href="#前端开发必备插件" aria-label="Permalink to &quot;前端开发必备插件&quot;">​</a></h2><p>eslint、stylelint、VS Code JavaScript (ES6) snippets、Prettier</p><h2 id="vue2-开发插件包" tabindex="-1">Vue2 开发插件包 <a class="header-anchor" href="#vue2-开发插件包" aria-label="Permalink to &quot;Vue2 开发插件包&quot;">​</a></h2><p>vetur、vue-helper、Vue Snippets JS/HTML/PUG/Razor/PHP</p><h2 id="vue3-开发插件包" tabindex="-1">Vue3 开发插件包 <a class="header-anchor" href="#vue3-开发插件包" aria-label="Permalink to &quot;Vue3 开发插件包&quot;">​</a></h2><p>TypeScript Vue Plugin (Volar)、Vue Language Features (Volar)</p><h2 id="uni-app-开发插件包" tabindex="-1">UNI-APP 开发插件包 <a class="header-anchor" href="#uni-app-开发插件包" aria-label="Permalink to &quot;UNI-APP 开发插件包&quot;">​</a></h2><p>Uni App Snippets <img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331141256231.png?imageMogr2/quality/70" alt="image-20230331141256231"></p><p>uni-create-view</p><p>快速创建uniapp视图与组件</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-exts.gif?imageMogr2/quality/70" alt="img"></p><h2 id="功能扩展" tabindex="-1">功能扩展 <a class="header-anchor" href="#功能扩展" aria-label="Permalink to &quot;功能扩展&quot;">​</a></h2><p>Code Spell Checker <strong>强烈推荐</strong> 检测英文单词拼写 当单词不正常的时候，就会在下方出现波浪线进行提示，还可以自定义词典，忽略某个单词的检查等</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331111720436.png?imageMogr2/quality/70" alt="image-20230331111720436"></p><p>GitLens — Git supercharged</p><p>VS Code 增强 Git 的功能</p><p><strong>强烈建议安装插件<code>GitLens</code>, 它是 VS Code 中我最推荐的一个插件, 简直是 Git 神器, 码农必备。</strong></p><p>GitLens 在 Git 管理上有很多强大的功能, 比如：</p><ul><li>将光标放置在代码的当前行, <code>可以看到这行代码的提交者是谁</code>, 以及提交时间。这一点, 是 GitLens 最便捷的功能。</li><li>查看某个 commit 的代码改动记录</li><li>查看不同的分支</li><li>可以将两个 commit 进行代码对比</li><li>甚至可以将两个 branch 分支进行整体的代码对比。这一点, 简直是 GitLens 最强大的功能。当我们在不同分支 review 代码的时候, 就可以用到这一招。</li></ul><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331112821623.png?imageMogr2/quality/70" alt="image-20230331112821623"></p><p>Image preview</p><p>可以直接在代码里面的预览引用的图片</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331113915868.png?imageMogr2/quality/70" alt="image-20230331113915868"></p><p>Bookmarks 代码书签</p><p>它可以轻松快速地在代码中的重要位置之间移动，不再需要寻找代码，它还包括一组选择命令，用于选择带书签的行和带书签的行之间的区域</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331131055515.png?imageMogr2/quality/70" alt="image-20230331131055515"></p><p>EditorConfig for VS Code</p><p>帮助开发人员在不同的编辑器和IDE之间定义和维护一致的编码样式。EditorConfig项目由用于定义编码样式<strong>的文件格式</strong>和一组<strong>文本编辑器插件组成</strong>，这些<strong>插件</strong>使编辑器能够读取文件格式并遵循定义的样式。EditorConfig文件易于阅读，并且与版本控制系统配合使用</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331133436342.png?imageMogr2/quality/70" alt="image-20230331133436342"></p><p>Project Manager</p><p>项目管理器 方便来回切换多个项目 保存项目到 vscode 中</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331135037518.png?imageMogr2/quality/70" alt="image-20230331135037518"></p><p>open in browser</p><p>方便 预览当前打开的文件</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331135244072.png?imageMogr2/quality/70" alt="image-20230331135244072"></p><p>JSON to TS</p><p>自动把 <code>json</code> 格式转成 <code>ts</code> 的类型，复制 <code>json</code> 之后按 <code>ctrl + shift + alt + v</code> 即可</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-clipboard.gif?imageMogr2/quality/70" alt="From clipboard"></p><h2 id="提升编码效率" tabindex="-1">提升编码效率 <a class="header-anchor" href="#提升编码效率" aria-label="Permalink to &quot;提升编码效率&quot;">​</a></h2><p>change-case <strong>强烈推荐</strong></p><p>帮助你快速修改代码风格</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331114508884.png?imageMogr2/quality/70" alt="image-20230331114508884"></p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-1a9019e8-7a9c-11e5-8f06-91fd2d7e21bf.gif?imageMogr2/quality/70" alt="change-case-multi"></p><p>CSS Variable Autocomplete</p><p>自动提示css 声明变量 跳转变量声明位置</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331130740535.png?imageMogr2/quality/70" alt="image-20230331130740535"></p><p>Path Autocomplete</p><p>自动提示文件路径</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-path-autocomplete.gif?imageMogr2/quality/70" alt="demo gif"></p><p>Svg Preview</p><p>预览SVG</p><p><img src="https://github.com/SimonSiefke/vscode-svg-preview/raw/master/demo_images/demo.gif" alt="demo"></p><p>REST Client</p><p>可以帮助我们在日常的接口开发过程中简化接口的请求调试方式，并加速开发进程</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331135939111.png?imageMogr2/quality/70" alt="image-20230331135939111"></p><h2 id="其它插件" tabindex="-1">其它插件 <a class="header-anchor" href="#其它插件" aria-label="Permalink to &quot;其它插件&quot;">​</a></h2><p>TODO Highlight</p><p>写代码过程中, 突然发现一个 Bug, 但是又不想停下来手中的活, 以免打断思路, 怎么办？按照代码规范, 我们一般是在代码中加个 TODO 注释</p><p>比如：（注意, 一定要写成大写<code>TODO</code>, 而不是小写的<code>todo</code>）</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331141056999.png?imageMogr2/quality/70" alt="image-20230331141056999"></p><p>Code Translate</p><p>代码划词翻译 英语学习</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331114643426.png?imageMogr2/quality/70" alt="image-20230331114643426"></p><p>Doxygen Documentation Generator</p><p>自动生成 代码注释模板</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331133034232.png?imageMogr2/quality/70" alt="image-20230331133034232"></p><p>Polacode-2022</p><p>方便把代码导出图片保存分享</p><p><img src="https://github.com/octref/polacode/raw/master/demo/usage.gif" alt="usage"></p><p>会了吧</p><p>还是一个 英语学习插件</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/2023-05-07-17-10-01-image-20230331144533276.png?imageMogr2/quality/70" alt="image-20230331144533276"></p>',104)])])}const u=i(o,[["render",g]]);export{d as __pageData,u as default};
